// Разбор JSON Lines из всех прочитанных файлов (основной + *_synthetic.jsonl)
const out = [];
for (const item of $input.all()) {
  const text = item.json.data || '';
  for (const line of text.split(/\r?\n/)) {
    const t = line.trim();
    if (!t) continue;
    try { out.push({ json: JSON.parse(t) }); } catch (e) { /* битая строка — пропуск */ }
  }
}
return out;

function normalizeText(s) {
  if (s === null || s === undefined) return s;
  s = String(s).normalize('NFKC').replace(/ /g, ' ').replace(/[​-‍⁠﻿]/g, '');
  return s.replace(/\s+/g, ' ').trim();
}
const TR = {а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',
  п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'shch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya'};
function slugify(s) {
  s = normalizeText(String(s || '')).toLowerCase();
  s = [...s].map(ch => TR[ch] ?? ch).join('');
  return s.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
function stripTracking(u) {
  u = String(u || '');
  if (!u.includes('?')) return u;
  let [base, q] = u.split('?');
  q = q.split('&').filter(p => !/^(utm_[^=]+|ref|fbclid|gclid|yclid)=/.test(p)).join('&');
  return q ? `${base}?${q}` : base;
}
// NaN между узлами n8n превращается в null, поэтому ошибки типизации копим в _type_errors
function toNum(v, field, errs) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = Number(String(v).trim().replace(',', '.'));
  if (Number.isFinite(n)) return n;
  errs.push(`${field}: не число (${JSON.stringify(v)})`);
  return null;
}

return $input.all().map(({ json: r }) => {
  const city = normalizeText(r.city_raw);
  const errs = [];
  return { json: {
    location_id: slugify(city), city,
    latitude: toNum(normalizeText(r.latitude_raw), 'latitude', errs),
    longitude: toNum(normalizeText(r.longitude_raw), 'longitude', errs),
    _type_errors: errs,
    source: r._source, source_url: stripTracking(r._source_url), parser_version: String(r._parser_version),
    collected_at: r._collected_at, synthetic: r._synthetic_corruption || null,
  }};
});

return $input.all().map(({ json: r }) => {
  const errs = [...(r._type_errors || [])];
  if (!r.city || r.city.length < 2) errs.push('city: пусто или короче 2 символов');
  if (errs.length === 0 && (r.latitude === null || r.longitude === null)) errs.push('координаты: пропуск');
  else if (r.latitude !== null && r.longitude !== null) {
    if (r.latitude < 41 || r.latitude > 82) errs.push('широта вне территории России');
    if (!((r.longitude >= 19 && r.longitude <= 180) || (r.longitude >= -180 && r.longitude <= -168))) errs.push('долгота вне территории России');
  }
  if (r.city && !/^[А-ЯЁ][А-Яа-яЁё\- .()]+$/.test(r.city)) errs.push('название не кириллицей с заглавной');
  return { json: { ...r, _valid: errs.length === 0, _reason: errs.join('; ') } };
});

