return $input.all().map(({ json: r }) => {
  const city = normalizeText(r.city_raw);
  const location_id = slugify(city);
  const errs = [];
  const d = normalizeText(r.date_raw);
  const ok = /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(new Date(d + 'T00:00:00Z')) &&
