    collected_at: r._collected_at, synthetic: r._synthetic_corruption || null,
  }};
});

const today = new Date(); today.setUTCHours(0, 0, 0, 0);
const num = v => typeof v === 'number' && Number.isFinite(v);
return $input.all().map(({ json: r }) => {
  const errs = [...(r._type_errors || [])];
  if (!r.observation_time_utc) errs.push('дата: не распознана');
  else if (new Date(r.observation_time_utc) > today) errs.push('дата в будущем');
  for (const f of ['temperature_2m_max', 'temperature_2m_min']) {
    if (r[f] === null) { if (!errs.some(e => e.startsWith(f))) errs.push(`${f}: пропуск`); }
    else if (r[f] < -70 || r[f] > 50) errs.push(`${f}: вне [-70; 50]`);
  }
  if (num(r.temperature_2m_max) && num(r.temperature_2m_min)) {
    if (r.temperature_2m_max < r.temperature_2m_min) errs.push('tmax < tmin');
    if (r.temperature_2m_max - r.temperature_2m_min > 40) errs.push('размах > 40');
  }
  if (r.precipitation_sum !== null && (!num(r.precipitation_sum) || r.precipitation_sum < 0 || r.precipitation_sum > 300))
    errs.push('осадки вне [0; 300]');
  return { json: { ...r, _valid: errs.length === 0, _reason: errs.join('; ') } };
});

